    ["Quest reward."] = "Questbelohnung.",
    ["Alliance: collect the Head of the Baron in the Ruins of Lordaeron and bring it to Captain Truman."] = "Allianz: Hol den Kopf des Barons aus den Ruinen von Lordaeron und bring ihn zu Hauptmann Truman.",
    ["Horde: report to Master Apothecary Faranell in Undercity."] = "Horde: Melde dich bei Meisterapotheker Faranell in Unterstadt.",
    ["One of the reward choices."] = "Eine der wählbaren Belohnungen.",
    ["Reward from Abominable Creatures (Alliance) or Unending Torment (Horde)."] = "Belohnung aus „Abominable Creatures“ (Allianz) oder „Unending Torment“ (Horde).",
    ["ProgressStep right up, step right up! &nbsp;If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so! &nbsp;You can redeem tickets in various denominations for wondrous and fantastic prizes. &nbsp;Don't be shy, give it a try!"] = "Hereinspaziert, hereinspaziert! Wenn Ihr Lose vom Dunkelmond-Jahrmarkt eintauschen wollt, sagt es einfach! Ihr könnt Lose in verschiedenen Mengen gegen wundersame und fantastische Preise eintauschen. Nur keine Scheu, versucht es!",
    ["Pick it over the other reward choices."] = "Wähle sie statt der anderen Belohnungen.",
    ["The reward is mailed to you after you finish the quest."] = "Die Belohnung wird dir nach Abschluss der Quest per Post geschickt.",
    ["ProgressAvast Lubber! &nbsp; Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena! &nbsp; Arrrr!"] = "Ahoi, Landratte! Bringt mir 12 Schmuckstücke des Arenameisters, dann sollt Ihr Großmeister der Arena der Gurubashi werden! Arrrr!",
    ["ProgressIf you bring me thirty necrotic runes, I will give you your choice of hand protection in return."] = "Wenn Ihr mir dreißig nekrotische Runen bringt, gebe ich Euch dafür einen Handschutz Eurer Wahl.",
    ["These should prove valuable in our fight against the undead Scourge."] = "Diese sollten sich in unserem Kampf gegen die untote Geißel als wertvoll erweisen.",
    ["War comes, &lt;name&gt;, and with it comes untold horrors."] = "Der Krieg kommt, <name>, und mit ihm unsagbare Schrecken.",
    ["You have done all that could be asked of you and for that you should be rewarded.Should this... this prophecy ever come to pass...The future of us all could be at an end.These armaments will prove invaluable to your campaign in this desert."] = "Ihr habt alles getan, was man von Euch verlangen konnte, und dafür sollt Ihr belohnt werden. Sollte diese... diese Prophezeiung je eintreten... könnte das Ende von uns allen gekommen sein. Diese Rüstungen werden Euch bei Eurem Feldzug in dieser Wüste unschätzbare Dienste leisten.",
    ["Your garment is ready! &nbsp;And that silk you gathered was so nice... you don't mind if I made it a little short so that I'd have some silk left over for me, do you?I'm only joking. &nbsp;It'll fit you great, and will be perfect for both adventure and formal dining. &nbsp;Enjoy!"] = "Euer Gewand ist fertig! Und die Seide, die Ihr gesammelt habt, war so schön... Ihr habt doch nichts dagegen, dass ich es ein wenig kürzer gemacht habe, damit mir etwas Seide übrig bleibt? Nur ein Scherz. Es wird Euch hervorragend passen und ist perfekt für Abenteuer wie für festliche Dinner. Viel Freude damit!",
    ["Thank you, &lt;name&gt;. &nbsp;These gauntlets are my best work. &nbsp;Take them."] = "Danke, <name>. Diese Stulpen sind meine beste Arbeit. Nehmt sie.",
    ["In wearing them, you bring honor to me and my ancestors."] = "Wenn Ihr sie tragt, ehrt Ihr mich und meine Ahnen.",
    ["I am sure you endured much hardship and shed much blood on my task, &lt;name&gt;. &nbsp;Here is the product of your toil.May you wear it well, and may you one day return here with stories of its service to you."] = "Ich bin sicher, Ihr habt für meine Aufgabe viel Mühsal ertragen und viel Blut vergossen, <name>. Hier ist der Lohn Eurer Mühen. Möget Ihr es gut tragen und eines Tages mit Geschichten über seine Dienste zurückkehren.",
    ["I give this helm to you.Great deeds brought you to me, &lt;name&gt;, and Earthmother willing... even greater deeds lie before you."] = "Ich gebe Euch diesen Helm. Große Taten haben Euch zu mir geführt, <name>, und so die Erdenmutter will... liegen noch größere Taten vor Euch.",
    ["A quest."] = "Eine Quest.",
    ["Always up to date."] = "Immer aktuell.",
    ["Here are your legguards, &lt;name&gt;. &nbsp;Let me know how they fit or if you need any modifications. &nbsp;I aim to please! &nbsp;At least I used to.These days I don't care much for my craft. &nbsp;But it beats being a mindless minion of the Scourge!I guess."] = "Hier sind Eure Beinschützer, <name>. Sagt mir, wie sie passen oder ob Ihr Änderungen braucht. Ich will Euch zufriedenstellen! Zumindest wollte ich das früher. Heutzutage liegt mir nicht mehr viel an meinem Handwerk. Aber es ist besser, als ein geistloser Diener der Geißel zu sein! Schätze ich.",
    ["You should be proud of yourself, &lt;name&gt;. &nbsp;Many mages have fallen to the creatures you faced.The Celestial Orb is ready. &nbsp;Or if you'd like I can mount it atop a staff. &nbsp;It's up to you. &nbsp;I'd prefer the orb, but who am I to judge?"] = "Ihr könnt stolz auf Euch sein, <name>. Viele Magier sind den Kreaturen erlegen, denen Ihr Euch gestellt habt. Die Himmlische Kugel ist bereit. Oder wenn Ihr wollt, kann ich sie auf einen Stab setzen. Es liegt bei Euch. Mir wäre die Kugel lieber, aber wer bin ich, darüber zu urteilen?",
    ["The Final Tablets are in Blackrock Spire."] = "Die letzten Tafeln befinden sich in der Schwarzfelsspitze.",
    ["ProgressSo many slain."] = "So viele Erschlagene.",
    ["Blood drenches the fields."] = "Blut tränkt die Felder.",
    ["Yet..."] = "Und doch...",
    ["You live..."] = "Ihr lebt...",
    ["You have persevered."] = "Ihr habt durchgehalten.",
    ["You have led our armies to many victories."] = "Ihr habt unsere Armeen zu vielen Siegen geführt.",
    ["For this, then, soldier, you have earned a new rank.Present your insignia."] = "Dafür, Soldat, habt Ihr Euch einen neuen Rang verdient. Zeigt Euer Abzeichen.",
    ["ProgressHow be that talisman, mon?"] = "Wie geht's dem Talisman, Mann?",
    ["It look like it be time to add a little more magic and mojo to its leaves."] = "Sieht aus, als wär's Zeit, seinen Blättern ein bisschen mehr Magie und Mojo zu geben.",
    ["It need a little bloom in its wilt."] = "Er braucht ein bisschen Blüte in seinem Welken.",
    ["Give it here and Maywiki fix it right up."] = "Gebt ihn her, und Maywiki bringt ihn wieder in Ordnung.",
    ["Sulhasa in southern Barrens wants you to clear out 7 Stormhide lizards and 7 Hecklefang Stalkers in the area so she can leave the tree safely."] = "Sulhasa im südlichen Brachland möchte, dass Ihr 7 Sturmhautechsen und 7 Hohnzahnpirscher in der Gegend beseitigt, damit sie den Baum sicher verlassen kann.",
    ["Reward from the quest 'Final Passage', the last of ten steps."] = "Belohnung der Quest „Final Passage“, dem letzten von zehn Schritten.",
    ["Bring Beginnings of the Undead Threat out of Scarlet Monastery Library."] = "Bringe „Beginnings of the Undead Threat“ aus der Bibliothek des Scharlachroten Klosters.",
    ["Pick the hammer over the other reward."] = "Wähle den Hammer statt der anderen Belohnung.",
    ["Pick the wand over the other reward."] = "Wähle den Zauberstab statt der anderen Belohnung.",
    ["This quest is offered after you turn in 10 library books to Garion Wendell in Stormwind or Owen Thadd in Undercity."] = "Diese Quest wird angeboten, nachdem du 10 Bibliotheksbücher bei Garion Wendell in Sturmwind oder Owen Thadd in Unterstadt abgegeben hast.",
    ["Here's your armor, &lt;name&gt;. &nbsp;This will stand up to the strongest assaults or my name isn't Furen Longbeard!And I have to thank you. &nbsp;I learned a lot while working with the materials you brought me. &nbsp;I think I'll have another breakthrough one day!I'm going to send what I learned to other blacksmiths of the Alliance.I'll tell them you were a big help, and maybe they'll want to return the favor."] = "Hier ist Eure Rüstung, <name>. Sie hält den stärksten Angriffen stand, oder ich heiße nicht Furen Langbart! Und ich muss Euch danken. Ich habe bei der Arbeit mit den Materialien, die Ihr mir gebracht habt, viel gelernt. Ich glaube, eines Tages gelingt mir noch ein Durchbruch! Ich werde, was ich gelernt habe, an andere Schmiede der Allianz weitergeben. Ich werde ihnen sagen, dass Ihr eine große Hilfe wart, und vielleicht wollen sie sich erkenntlich zeigen.",
    ["This quest is offered after you turn in 20 library books to Garion Wendell in Stormwind or Owen Thadd in Undercity."] = "Diese Quest wird angeboten, nachdem du 20 Bibliotheksbücher bei Garion Wendell in Sturmwind oder Owen Thadd in Unterstadt abgegeben hast.",
    ["Here are some weapons, hot off the anvil and made with the new umbral ore you brought me!Please, &lt;name&gt;, take your pick!"] = "Hier sind ein paar Waffen, frisch vom Amboss und aus dem neuen Schattenerz geschmiedet, das Ihr mir gebracht habt! Bitte, <name>, wählt aus!",
    ["A level 10 Quest."] = "Eine Quest der Stufe 10.",
    ["I can barely believe it! &nbsp;Furen's technique was a success, and this armor should withstand tremendous levels of stress.Here you are, &lt;name&gt;. &nbsp;And thank you. &nbsp;I wouldn't have believed Furen's discovery if you hadn't gathered the materials I needed to test it myself."] = "Ich kann es kaum glauben! Furens Technik war ein Erfolg, und diese Rüstung sollte gewaltigen Belastungen standhalten. Bitte sehr, <name>. Und danke. Ich hätte Furens Entdeckung nicht geglaubt, hättet Ihr nicht die Materialien gesammelt, die ich brauchte, um sie selbst zu prüfen.",
    ["I will keep three of the weapons you returned to me, as mementos of my pain and loss. &nbsp;But please, &lt;name&gt;, choose your favorite of the heirlooms and keep it for yourself.May it serve you greater than it served its cursed, former owners."] = "Drei der Waffen, die Ihr mir zurückgebracht habt, behalte ich als Andenken an meinen Schmerz und Verlust. Doch bitte, <name>, wählt Euer liebstes Erbstück und behaltet es. Möge es Euch besser dienen als seinen verfluchten früheren Besitzern.",
    ["As a hero of the Stormpike, you may choose one item from these recently plun... er, recovered treasures."] = "Als Held der Sturmlanzen dürft Ihr Euch einen Gegenstand aus diesen kürzlich erbeut... äh, geborgenen Schätzen aussuchen.",
    ["ProgressIt is good to see you again, &lt;class&gt;."] = "Es ist gut, Euch wiederzusehen, <class>.",
    ["I had not expected you to return."] = "Ich hatte nicht erwartet, dass Ihr zurückkehrt.",
    ["Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.Your time has come again, &lt;name&gt;."] = "Doch Ihr habt Euch als tapferer und ehrenhafter Soldat der Frostwölfe erwiesen. Eure Zeit ist wieder gekommen, <name>.",
    ["You have earned a new ranking and as such, a new insignia denoting this rise in stature.Present your insignia."] = "Ihr habt Euch einen neuen Rang verdient und damit ein neues Abzeichen, das Euren Aufstieg kennzeichnet. Zeigt Euer Abzeichen.",
    ["ProgressThe base buzzes with news of your exploits in the Field of Strife!"] = "Das Lager summt vor Nachrichten über Eure Taten auf dem Feld des Streits!",
    ["You have struck mighty blows against our enemy - crushing their morale!"] = "Ihr habt unserem Feind mächtige Schläge versetzt – und seine Moral zerschmettert!",
    ["For this, you have earned a rank of honor among the Stormpike.Present your insignia."] = "Dafür habt Ihr Euch einen Ehrenrang unter den Sturmlanzen verdient. Zeigt Euer Abzeichen.",
    ["Alliance only."] = "Nur Allianz.",
    ["Accept this talisman, &lt;class&gt;."] = "Nehmt diesen Talisman an, <class>.",
    ["Accept it and use its power to strike down our mutual enemies.Know that around your neck you carry a piece of history."] = "Nehmt ihn an und nutzt seine Macht, um unsere gemeinsamen Feinde niederzustrecken. Wisst, dass Ihr ein Stück Geschichte um Euren Hals tragt.",
    ["Kezan was once a grand territory of the Zandalar Empire."] = "Kezan war einst ein großes Gebiet des Reiches der Zandalari.",
    ["Alas, the taint of goblin trade princes would force out my proud brothers and sisters.Kezan is now home to the goblin capital of the Undermine; but know that before the taint, it held greatness."] = "Doch der Makel der Handelsprinzen der Goblins vertrieb meine stolzen Brüder und Schwestern. Kezan ist heute die Heimat der Goblinhauptstadt Lorenhall; doch wisst, dass es vor dem Makel Größe besaß.",
    ["Still to this day Kezan is considered sacred land to my people."] = "Bis heute gilt Kezan meinem Volk als heiliges Land.",
    ["ProgressCall forth your demons, &lt;class&gt;."] = "Ruft Eure Dämonen herbei, <class>.",
    ["Let them bask in the energy of Kezan's Taint."] = "Lasst sie in der Energie von Kezans Makel baden.",
    ["Command them on the field of battle!"] = "Befehligt sie auf dem Schlachtfeld!",
    ["Decimate the enemy!Yes..."] = "Dezimiert den Feind! Ja...",
    ["The time has come to apply the final enhancement to Kezan's Taint."] = "Die Zeit ist gekommen, Kezans Makel die letzte Verbesserung zu verleihen.",
    ["Give me the talisman."] = "Gebt mir den Talisman.",
    ["Here's your armor, &lt;name&gt;. &nbsp;Furen's process worked brilliantly! &nbsp;Perfectly! &nbsp;Marvelously, truly!You could run this armor over with a siege engine and it would spring right back into shape!"] = "Hier ist Eure Rüstung, <name>. Furens Verfahren hat glänzend funktioniert! Perfekt! Wahrhaft wunderbar! Ihr könntet mit einer Belagerungsmaschine über diese Rüstung fahren, und sie würde sofort wieder in Form springen!",
    ["ProgressBefore me stands an exalted hero of the Alliance.&lt;Lieutenant Haggerdin salutes.&gt;Few have earned such a rank among the Stormpike."] = "Vor mir steht ein ehrfürchtiger Held der Allianz. <Leutnant Haggerdin salutiert.> Nur wenige haben einen solchen Rang unter den Sturmlanzen erreicht.",
    ["I have watched the enemy fall before you."] = "Ich habe gesehen, wie der Feind vor Euch fiel.",
    ["I have seen their resolve crumble in your presence."] = "Ich habe gesehen, wie seine Entschlossenheit in Eurer Gegenwart zerbröckelte.",
    ["When you enter the fray, you become the beacon of hope for our forces!Present your insignia."] = "Wenn Ihr in den Kampf zieht, werdet Ihr zum Leuchtfeuer der Hoffnung für unsere Truppen! Zeigt Euer Abzeichen.",
    ["ProgressAn extremely sturdy cabinet stands before you, securely fastened shut by a built-in lock. &nbsp;The front of the cabinet is deeply scratched and marked. &nbsp;This could be surmised as being from numerous and violent failed attempts to reveal whatever secrets the cabinet currently obfuscates from view.If you are going to open this cabinet, you will need to find the key."] = "Vor Euch steht ein äußerst stabiler Schrank, sicher verschlossen durch ein eingebautes Schloss. Die Vorderseite ist tief zerkratzt und gezeichnet – wohl von zahlreichen gewaltsamen, gescheiterten Versuchen, die Geheimnisse zu lüften, die der Schrank verbirgt. Wenn Ihr diesen Schrank öffnen wollt, müsst Ihr den Schlüssel finden.",
    ["ProgressMolthor delivers word from King Rastakhan, &lt;name&gt;."] = "Molthor überbringt eine Nachricht von König Rastakhan, <name>.",
    ["The royal court is most impressed with your decimation of the Hakkari forces."] = "Der königliche Hof ist von Eurer Dezimierung der Streitkräfte der Hakkari sehr beeindruckt.",
    ["I am to award you with the final weave in your talisman."] = "Ich soll Euch die letzte Webung Eures Talismans verleihen.",
    ["Hand it to me."] = "Gebt ihn mir.",
    ["Rituals of Power sends you into Scarlet Monastery Library."] = "„Rituals of Power“ schickt dich in die Bibliothek des Scharlachroten Klosters.",
    ["Bring Bink her Mage-tastic Gizmonitor."] = "Bringt Bink ihren magietastischen Gizmonitor.",
    ["Here is your robe. &nbsp;It's one of my best made yet! &nbsp;Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!"] = "Hier ist Eure Robe. Sie ist eine meiner besten bisher! Tragt sie mit Stolz, und wenn die Leute fragen... sagt ihnen, Ihr habt sie bei Larsons Schneiderei bekommen!",
    ["I have finished with your piece of armor, and I am quite pleased. &nbsp;Furen's new techniques meshed perfectly with my own and I am sure this armor will prove to be quite resilient.Thank you, &lt;name&gt;. &nbsp;And may this serve you well in future battles."] = "Ich bin mit Eurem Rüstungsteil fertig und recht zufrieden. Furens neue Techniken passten perfekt zu meinen eigenen, und ich bin sicher, diese Rüstung wird sich als sehr widerstandsfähig erweisen. Danke, <name>. Möge sie Euch in künftigen Schlachten gute Dienste leisten.",
    ["&lt;name&gt;, your successful re-engineering of the cauldrons is a tremendous victory for us!Let all within my presence hear: for service to the Forsaken and to the Horde as a whole above and beyond what was expected - in the face of overwhelming odds and incredible danger, might I add - I give &lt;name&gt; this, and I extend upon him our undying gratitude as a true hero of the Horde. &nbsp;Huzzah!"] = "<name>, Eure erfolgreiche Umrüstung der Kessel ist ein gewaltiger Sieg für uns! Alle in meiner Gegenwart sollen hören: Für Dienste an den Verlassenen und der ganzen Horde, weit über das Erwartete hinaus – angesichts überwältigender Übermacht und unglaublicher Gefahr, möchte ich hinzufügen –, gebe ich <name> dies und spreche unseren ewigen Dank als wahrem Helden der Horde aus. Hurra!",
    ["Here is your nether-lace, &lt;name&gt;. &nbsp;It is both comfortable and durable, and holds the magic of the laughing sisters' hair.Enjoy, and if you find it amenable, please mention so to Deino. &nbsp;She is a &lt;class&gt; on whose good side I wish to stay..."] = "Hier ist Eure Netherspitze, <name>. Sie ist bequem und haltbar und birgt die Magie des Haares der lachenden Schwestern. Viel Freude damit, und wenn sie Euch gefällt, erwähnt es bitte bei Deino. Sie ist eine <class>, mit der ich es mir nicht verscherzen möchte...",
    ["Now isn't this interesting?"] = "Ist das nicht interessant?",
    ["You say you found this tablet on a small, deserted island at The Overlook Cliffs in The Hinterlands, &lt;class&gt;?"] = "Ihr sagt, Ihr habt diese Tafel auf einer kleinen, verlassenen Insel bei den Aussichtsklippen im Hinterland gefunden, <class>?",
    ["Very interesting indeed."] = "Wirklich sehr interessant.",
    ["I thank you for your efforts in this matter."] = "Ich danke Euch für Eure Mühen in dieser Angelegenheit.",
    ["Our Dark Lady shall be very pleased with this discovery."] = "Unsere Dunkle Fürstin wird über diese Entdeckung sehr erfreut sein.",
    ["Here, allow me to reward you proportionately."] = "Hier, lasst mich Euch angemessen belohnen.",
    ["Erlgadin in Stranglethorn Vale."] = "Erlgadin im Schlingendorntal.",
    ["Progress*Whir* *Click* &nbsp;I seek rare fish for Fishmaster Bluegill to catalogue. &nbsp; If you bring me a Keefer's Angelfish, I will provide you with this fine reward. *Zzzap* *Whir*."] = "*Surr* *Klick* Ich suche seltene Fische, die Fischmeister Blaukieme katalogisieren soll. Bringt Ihr mir einen Keefers Engelsfisch, gebe ich Euch diese feine Belohnung. *Zzzap* *Surr*.",
    ["Find what awaits you."] = "Findet, was Euch erwartet.",
    ["It will take time for our scholars to study the pendant you brought us. &nbsp;But for your service to the Horde I would like to offer you a small token.Thank you, &lt;name&gt;. &nbsp;Your acts bring honor to you, and to us."] = "Unsere Gelehrten werden Zeit brauchen, um den Anhänger zu studieren, den Ihr uns gebracht habt. Doch für Euren Dienst an der Horde möchte ich Euch ein kleines Zeichen anbieten. Danke, <name>. Eure Taten ehren Euch und uns.",
    ["Return the monogrammed silver hair clip to its owner."] = "Bringt die silberne Haarspange mit Monogramm ihrer Besitzerin zurück.",
    ["Here are your robes, &lt;name&gt;. &nbsp;Wear them well."] = "Hier sind Eure Roben, <name>. Tragt sie mit Würde.",
    ["ProgressIt is good to see you in good health, &lt;name&gt;."] = "Es ist gut, Euch bei guter Gesundheit zu sehen, <name>.",
    ["The glorious battles you have undertaken affect all life on this planet."] = "Die ruhmreichen Schlachten, die Ihr geschlagen habt, betreffen alles Leben auf dieser Welt.",
    ["Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.Give me your talisman and I shall amplify its strength."] = "Hakkar darf Zul'Gurub niemals verlassen, sonst wird die Welt sicher unter seinem gewaltigen Hunger zusammenbrechen. Gebt mir Euren Talisman, und ich werde seine Kraft verstärken.",
    ["Use the Strength of Mugamba to punish our enemies!"] = "Nutzt die Stärke von Mugamba, um unsere Feinde zu strafen!",
    ["ProgressDrek'Thar sings your praises."] = "Drek'Thar singt Euer Loblied.",
    ["Kalimdor is abuzz with tales of your heroics."] = "Ganz Kalimdor summt vor Geschichten über Eure Heldentaten.",
    ["The Warchief glows - your stalwart defense of our clan has pleased him greatly.You have earned the Eye of Command.Present your insignia, Commander &lt;name&gt;."] = "Der Kriegshäuptling strahlt – Eure standhafte Verteidigung unseres Clans hat ihn sehr erfreut. Ihr habt Euch das Auge des Befehls verdient. Zeigt Euer Abzeichen, Kommandant <name>.",
    ["ProgressTales of your battles against the Gurubashi are whispered in the winds, &lt;class&gt;."] = "Geschichten über Eure Kämpfe gegen die Gurubashi werden im Wind geflüstert, <class>.",
    ["Even royalty is beginning to talk of your deeds."] = "Selbst die Könige beginnen, von Euren Taten zu sprechen.",
    ["It is rumored that King Rastakhan even mentioned you by name.The time has come to imbue the Eye."] = "Es heißt, König Rastakhan habe Euch sogar beim Namen genannt. Die Zeit ist gekommen, das Auge zu durchdringen.",
    ["Hand me the talisman and I shall perform the service."] = "Reicht mir den Talisman, und ich werde den Dienst verrichten.",
    ["ProgressNever have I seen such tenacity!"] = "Nie habe ich solche Beharrlichkeit gesehen!",
    ["The Bronze Flight grants you one final enchantment."] = "Der bronzene Drachenschwarm gewährt Euch eine letzte Verzauberung.",
    ["The Timeless One himself has requested it so!Hand me your signet ring so that I may make the necessary adjustments."] = "Der Zeitlose selbst hat es so verlangt! Reicht mir Euren Siegelring, damit ich die nötigen Anpassungen vornehmen kann.",
    ["Know this, heathen: A catastrophe has brought us together."] = "Wisst dies, Heide: Eine Katastrophe hat uns zusammengeführt.",
    ["Your pagan ways are neither understood nor appreciated by Zandalar but we are a fair people."] = "Eure heidnischen Sitten werden von den Zandalar weder verstanden noch geschätzt, doch wir sind ein gerechtes Volk.",
    ["Wear this brand around your neck."] = "Tragt dieses Brandzeichen um Euren Hals.",
    ["It shall serve as both a warning to our enemies and a symbol of your friendship to Zandalar.Continue to serve our people and I will amplify the power of the brand."] = "Es soll unseren Feinden als Warnung und als Symbol Eurer Freundschaft zu den Zandalar dienen. Dient unserem Volk weiter, und ich werde die Macht des Brandzeichens verstärken.",
    ["&lt;name&gt;, you have slain all three beasts that comprise the Ashenvale Hunt. &nbsp;You have brought me adequate proof of their demise; there is no question of your strength and tenacity. &nbsp;The blood of a hunter streaks through your veins, and you should be commended!Please, accept this bauble as a sign of congratulations on your mighty deeds done in Ashenvale for the Horde today. &nbsp;May your ancestors watch over you!"] = "<name>, Ihr habt alle drei Bestien erschlagen, die zur Jagd im Eschental gehören. Ihr habt mir ausreichende Beweise für ihr Ende gebracht; an Eurer Stärke und Beharrlichkeit besteht kein Zweifel. Das Blut eines Jägers fließt durch Eure Adern, und dafür gebührt Euch Lob! Bitte nehmt diesen Tand als Glückwunsch zu Euren mächtigen Taten, die Ihr heute im Eschental für die Horde vollbracht habt. Mögen Eure Ahnen über Euch wachen!",
    ["ProgressAh, &lt;name&gt;, it is good to smell you again.You'll have to excuse my sense of humor."] = "Ah, <name>, es ist gut, Euch wieder zu riechen. Ihr müsst meinen Humor entschuldigen.",
    ["It can be most foul at times.I sense that you have caused great anguish to our enemies."] = "Er kann manchmal sehr übel sein. Ich spüre, dass Ihr unseren Feinden großes Leid zugefügt habt.",
    ["The forces of Hakkar cry out your name in anger."] = "Die Streitkräfte Hakkars rufen voller Zorn Euren Namen.",
    ["This is most excellent.You have earned another weave on your talisman."] = "Das ist ganz ausgezeichnet. Ihr habt Euch eine weitere Webung Eures Talismans verdient.",
    ["ProgressKing Rastakhan sends his regards, Master &lt;name&gt;."] = "König Rastakhan lässt grüßen, Meister <name>.",
    ["Such an honor has never been given to one outside the Zandalar tribe.Give me your talisman so that I may enhance it once more."] = "Eine solche Ehre wurde noch nie jemandem außerhalb des Stammes der Zandalar zuteil. Gebt mir Euren Talisman, damit ich ihn noch einmal verbessern kann.",
    ["Know that the Rage of Mugamba is now intrinsically connected to your very soul."] = "Wisst, dass die Wut von Mugamba nun untrennbar mit Eurer Seele verbunden ist.",
    ["Greetings, champion."] = "Seid gegrüßt, Champion.",
    ["I am Jonathan, keeper of the sacred gong and eternal watcher of the Bronze Flight.I have been empowered by the Timeless One himself to grant you an item of your choosing from his timeless treasure trove."] = "Ich bin Jonathan, Hüter des heiligen Gongs und ewiger Wächter des bronzenen Drachenschwarms. Der Zeitlose selbst hat mich ermächtigt, Euch einen Gegenstand Eurer Wahl aus seinem zeitlosen Schatz zu gewähren.",
    ["May it aid you in your battles against C'Thun."] = "Möge er Euch in Euren Kämpfen gegen C'Thun beistehen.",
    ["Help Walton survive the encounter with Terry Longdrink and the Kul Tiras marines."] = "Hilf Walton, die Begegnung mit Terry Longdrink und den Marines von Kul Tiras zu überleben.",
    ["Deathstalker Masoj needs you to place the three Apothecary Vials on peaks around Hillsbrad Foothills and return to him."] = "Todespirscher Masoj möchte, dass du die drei Fläschchen des Apothekers auf Gipfeln im Vorgebirge des Hügellands platzierst und zu ihm zurückkehrst.",
    ["ProgressSha-mon!"] = "Scha-Mann!",
    ["Maywiki make a joke!&lt;Maywiki laughs.&gt;So, you been using the spirits and elements against our enemies in Zul'Gurub, eh?"] = "Maywiki macht 'nen Witz! <Maywiki lacht.> Ihr habt also die Geister und Elemente gegen unsere Feinde in Zul'Gurub eingesetzt, was?",
    ["Spirits be praised!Maywiki gonna brighten your orb."] = "Gepriesen seien die Geister! Maywiki wird Eure Kugel aufhellen.",
    ["Give it here, &lt;name&gt;."] = "Gebt her, <name>.",
    ["Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post."] = "Erschlage Arnak Grimmtotem und bringe den Beweis deiner Tat zu Klippenwächter Langhorn im Freiwindposten.",
    ["Reward from the quest 'Wanted!"] = "Belohnung der Quest „Wanted!",
    ["Marez Cowl'."] = "Marez Cowl“.",
    ["Otto and Falconcrest'."] = "Otto and Falconcrest“.",
    ["&lt;name&gt;, I have crafted these weapons with the elunite you brought to me. &nbsp;Please, take whichever most suits you.And I must thank you. &nbsp;Working with elunite is both an honor and a pleasure."] = "<name>, ich habe diese Waffen aus dem Elunit gefertigt, das Ihr mir gebracht habt. Bitte nehmt, was Euch am besten passt. Und ich muss Euch danken. Mit Elunit zu arbeiten ist mir Ehre und Freude zugleich.",
    ["I have the whirlwind heart, and am ready to place it within your vessel of choice.Choose your weapon, &lt;name&gt;, and know that its power is the power of Cyclonian."] = "Ich habe das Wirbelwindherz und bin bereit, es in das Gefäß Eurer Wahl einzusetzen. Wählt Eure Waffe, <name>, und wisst, dass ihre Macht die Macht von Cyclonian ist.",
    ["ProgressIt yearns to grow, &lt;name&gt;."] = "Er sehnt sich danach zu wachsen, <name>.",
    ["The talisman has soaked in all that you have done."] = "Der Talisman hat alles in sich aufgesogen, was Ihr getan habt.",
    ["The thousands of troll corpses littering Zul'Gurub have fueled its power."] = "Die Tausenden Trollleichen, die Zul'Gurub übersäen, haben seine Macht genährt.",
    ["Hand it to me and I shall make the final enhancement."] = "Reicht ihn mir, und ich werde die letzte Verbesserung vornehmen.",
    ["ProgressImpressive, &lt;name&gt;."] = "Beeindruckend, <name>.",
    ["You have a gift for killing that I have not sensed in another in many years."] = "Ihr habt eine Gabe zum Töten, wie ich sie seit vielen Jahren bei niemandem mehr gespürt habe.",
    ["Even Molthor is aware of the work that you have done for Zandalar."] = "Selbst Molthor weiß um die Arbeit, die Ihr für die Zandalar geleistet habt.",
    ["It is time to enhance your talisman further."] = "Es ist Zeit, Euren Talisman weiter zu verbessern.",
    ["Give it to me."] = "Gebt ihn mir.",
    ["A Gnomeregan oddity whose Use effect grants a huge burst of attack speed."] = "Eine Kuriosität aus Gnomeregan, deren Benutzen-Effekt einen enormen Schub an Angriffstempo gewährt.",
    ["Feral druids kept it for that alone, because it works in cat form -- and it has limited charges, so every use is a decision."] = "Wilde Druiden behielten sie allein deshalb, weil sie in Katzengestalt funktioniert – und sie hat begrenzte Aufladungen, also ist jede Nutzung eine Entscheidung.",
    ["A Nightmare-corrupted green dragon who splits himself into shades rather than face a fight whole."] = "Ein vom Albtraum verderbter grüner Drache, der sich lieber in Schemen aufspaltet, als sich einem Kampf als Ganzes zu stellen.",
    ["A blue dragon slain in Northrend and raised as a frost wyrm."] = "Ein blauer Drache, in Nordend erschlagen und als Frostwyrm erweckt.",
    ["He guards the final approach to Kel'Thuzad's chamber."] = "Er bewacht den letzten Zugang zu Kel'Thuzads Kammer.",
    ["A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate."] = "Auf den Kopf von Marez Cowl, einer hochrangigen Beraterin und Agentin des Syndikats, ist ein Kopfgeld ausgesetzt.",
    ["She was last seen within the Syndicate controlled territory of Stromgarde."] = "Sie wurde zuletzt im vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.",
    ["A core hound of the deep fire, kept as a guard beast and fed by Ragnaros's lieutenants."] = "Ein Kernhund des tiefen Feuers, als Wachtier gehalten und von Ragnaros' Leutnants gefüttert.",
    ["A crafted helm that outlived several tiers of raid gear."] = "Ein hergestellter Helm, der mehrere Stufen an Schlachtzugsausrüstung überdauerte.",
    ["Its plans were the thing guilds actually fought over."] = "Um seine Pläne haben sich Gilden tatsächlich gestritten.",
    ["A crypt lord of Azjol-Nerub who took Arthas's side."] = "Ein Gruftlord von Azjol-Nerub, der sich auf Arthas' Seite schlug.",
    ["He holds the Arachnid Quarter's outermost hall."] = "Er hält die äußerste Halle des Arachnidenviertels.",
    ["A death knight who trains the Scourge's new officers."] = "Ein Todesritter, der die neuen Offiziere der Geißel ausbildet.",
    ["He is too strong for his own students to touch, which is exactly the point of the lesson."] = "Er ist zu stark, als dass seine eigenen Schüler ihn berühren könnten – und genau das ist der Sinn der Lektion.",
    ["A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."] = "Ein Pilzschrecken, gezüchtet in den Sporenbottichen des Seuchenviertels – weniger eine Kreatur als eine Ernte, die außer Kontrolle geriet.",
    ["A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs."] = "Eine riesige Spinne, eingesponnen in den Tiefen des Arachnidenviertels und gefüttert mit allem, was die Geißel nicht mehr braucht.",
    ["A green dragon of Ysera's flight, turned by the Nightmare and hunted across Feralas ever since."] = "Ein grüner Drache aus Yseras Schwarm, vom Albtraum verwandelt und seitdem quer durch Feralas gejagt.",
    ["A hound handler of Ragnaros's court, who curses healing shut before the fighting starts."] = "Ein Hundeführer von Ragnaros' Hof, der Heilung verflucht, bevor der Kampf beginnt.",
    ["A human lord who traded his life for undeath and became a lich in Scholomance."] = "Ein menschlicher Fürst, der sein Leben gegen das Unleben tauschte und in Scholomance zum Lich wurde.",
    ["Killing him takes a blade specifically made to sever the bargain."] = "Um ihn zu töten, braucht es eine Klinge, die eigens geschaffen wurde, um diesen Pakt zu durchtrennen.",
    ["A lieutenant of Ragnaros who fights surrounded by his Firesworn, and grows stronger each time one of them falls."] = "Ein Leutnant von Ragnaros, der umgeben von seinen Feuerschwörern kämpft und jedes Mal stärker wird, wenn einer von ihnen fällt.",
    ["A living mass of qiraji poison."] = "Eine lebende Masse aus Qiraji-Gift.",
    ["It has to be frozen solid and then shattered, which is not how most things die."] = "Sie muss steinhart gefroren und dann zerschmettert werden – so sterben die wenigsten Dinge.",
    ["A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."] = "Ein Nekromant des Seuchenviertels, befördert für sein Geschick, zu erwecken, was er gerade erst getötet hatte.",
    ["A pit lord left behind when the Legion's invasion collapsed, still holding the Tainted Scar where the Dark Portal's blast burned the land."] = "Ein Grubenlord, zurückgelassen, als die Invasion der Legion zusammenbrach, und noch immer Herr über die Verderbte Narbe, wo die Explosion des Dunklen Portals das Land verbrannte.",
    ["A plain plate glove that became famous for its random enchants -- the of Strength roll is a 7.9% chance and was worth chasing over guaranteed epics for years."] = "Ein schlichter Plattenhandschuh, berühmt für seine zufälligen Verzauberungen – „der Stärke“ hat eine Chance von 7,9 % und war jahrelang die Jagd wert, noch vor garantierten Epics.",
    ["A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."] = "Eine Prinzessin der Erdelementare und der Grund, warum Maraudon vergiftet ist – in seinem Herzen hält sie den Körper von Zaetar, ihrem Halbgott-Gemahl.",
    ["A qiraji brood matron whose poison is potent enough that the fight is really a race against her venom."] = "Eine Brutmutter der Qiraji, deren Gift so stark ist, dass der Kampf eigentlich ein Wettlauf gegen ihr Gift ist.",
    ["A red dragon of Alexstrasza's flight, broken by Nefarian's experiments."] = "Ein roter Drache aus Alexstraszas Schwarm, gebrochen durch Nefarians Experimente.",
    ["He asks to be killed before the corruption finishes taking him, and apologises while he fights."] = "Er bittet darum, getötet zu werden, bevor die Verderbnis ihn ganz übernimmt, und entschuldigt sich, während er kämpft.",
    ["A sandworm grown enormous under the desert, surfacing only to feed."] = "Ein Sandwurm, unter der Wüste riesig geworden, der nur zum Fressen an die Oberfläche kommt.",
    ["A stitched hound kept half-starved on purpose, so it would eat anything the Construct Quarter sent its way."] = "Ein zusammengenähter Hund, absichtlich halb verhungert gehalten, damit er alles frisst, was das Konstruktviertel ihm schickt.",
    ["A stone giant pressed into qiraji service, who drains the mana of everyone fighting him and turns to rock when full."] = "Ein Steinriese im Dienst der Qiraji, der allen Kämpfenden das Mana entzieht und zu Stein wird, wenn er voll ist.",
    ["A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."] = "Ein gewaltiger Qiraji-Gräber, der mitten im Kampf seine Brut hervorbringt und Eindringlinge gegen die Wände schleudert.",
    ["A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."] = "Eine Anhängerin Kel'Thuzads, die ihre Gefolgsleute mit ins Unleben nahm und sie noch immer befehligt.",
    ["An Old God, buried under Ahn'Qiraj by the titans rather than killed."] = "Ein Alter Gott, von den Titanen unter Ahn'Qiraj begraben statt getötet.",
    ["It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."] = "Seitdem flüstert er den Qiraji zu, und der ganze Krieg existiert nur, weil er nie damit aufgehört hat.",
    ["An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."] = "Eine Monstrosität, aus den Resten der Geißel zusammengenäht und für nichts als rohe Kraft gebaut.",
    ["Archmage Arugal called the worgen to Silverpine to defend against the Scourge, lost control of them immediately, and went mad in Shadowfang Keep among the things he had summoned."] = "Erzmagier Arugal rief die Worgen nach Silberwald, um sich gegen die Geißel zu verteidigen, verlor sofort die Kontrolle über sie und verfiel in der Burg Schattenfang dem Wahnsinn, umgeben von dem, was er beschworen hatte.",
    ["Arugal's own belt."] = "Arugals eigener Gürtel.",
    ["He summoned the worgen to save Silverpine, then lost his mind in Shadowfang Keep surrounded by what he had called."] = "Er beschwor die Worgen, um Silberwald zu retten, und verlor dann in der Burg Schattenfang den Verstand, umgeben von dem, was er gerufen hatte.",
    ["Avast Lubber!"] = "Ahoi, Landratte!",
    ["Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!"] = "Bringt mir 12 Schmuckstücke des Arenameisters, dann sollt Ihr Großmeister der Arena der Gurubashi werden!",
    ["C'Thun's mouthpiece."] = "C'Thuns Sprachrohr.",
    ["Everything the qiraji believe, they believe because he told them the Old God said it."] = "Alles, was die Qiraji glauben, glauben sie, weil er ihnen sagte, der Alte Gott habe es gesagt.",
    ["Cut from the fang of one of Nefarian's drakes."] = "Aus dem Reißzahn eines von Nefarians Drachen geschnitten.",
    ["Tanks wore it for the stun it shrugs off, not the numbers on it."] = "Tanks trugen ihn wegen der Betäubung, die er abwehrt, nicht wegen der Werte darauf.",
    ["Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five."] = "Todesschwinges Sohn, der unter dem Schwarzfels die chromatischen Drachen züchtet – Drachen mit dem Blut aller fünf Schwärme.",
    ["He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."] = "Er verbrachte Jahre als Lord Victor Nefarius an Sturmwinds Hof, während die Arbeit weiterging.",
    ["Ghamoo-ra is the ancient turtle the naga keep in Blackfathom Deeps -- old enough that the Twilight cultists there treat it as part of the temple."] = "Ghamoo-ra ist die uralte Schildkröte, die die Naga in der Tiefschwarzen Grotte halten – so alt, dass die Kultisten des Schattenhammers sie als Teil des Tempels betrachten.",
    ["Hakkar's chief hexxer, who fights by binding pieces of his enemies' spirits and setting them loose."] = "Hakkars oberster Hexer, der kämpft, indem er Teile der Geister seiner Feinde bindet und freilässt.",
    ["He has overpowered all attempts at his capture."] = "Er hat sich allen Versuchen, ihn zu fangen, widersetzt.",
    ["The Stormwind Army has placed a generous bounty on the Gnoll."] = "Die Armee von Sturmwind hat ein großzügiges Kopfgeld auf den Gnoll ausgesetzt.",
    ["I had not expected you to return."] = "Ich hatte nicht erwartet, dass Ihr zurückkehrt.",
    ["Alas, you have proven yourself a brave and honorable soldier of the Frostwolf."] = "Doch Ihr habt Euch als tapferer und ehrenhafter Soldat der Frostwölfe erwiesen.",
    ["Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."] = "Hüter der Seuchenwerke von Naxxramas und des Korridors der Eruptionen, der mehr Schlachtzügler getötet hat als er selbst.",
    ["Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."] = "Nefarians bestes Ergebnis: ein zweiköpfiger chromatischer Schrecken, der den Atem jedes Drachenschwarms zugleich in sich trägt.",
    ["Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly."] = "Einst ein Erzmagier der Kirin Tor, verließ er Dalaran, um den Kult der Verdammten zu gründen, und diente Ner'zhul aus freien Stücken.",
    ["Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."] = "In Andorhal getötet und als Lich erweckt, herrscht er von einem Phylakterium in ihrem Herzen aus über Naxxramas.",
    ["One of Hakkar's high priests, who returns to his feet twice before he stays down."] = "Einer von Hakkars Hohepriestern, der zweimal wieder aufsteht, bevor er liegen bleibt.",
    ["One of Nefarian's three guardian drakes, holding the suspended walkways above the lair floor."] = "Einer von Nefarians drei Wächterdrachen, der die schwebenden Stege über dem Boden des Unterschlupfs hält.",
    ["One of Ysera's four green consorts, corrupted by the Emerald Nightmare and now roaming Feralas, rotting the ground it stands on."] = "Einer von Yseras vier grünen Gefährten, verderbt durch den Smaragdgrünen Albtraum und nun in Feralas umherstreifend, wo er den Boden unter sich verrotten lässt.",
    ["One of the three qiraji councillors who fight as one -- kill any of them and the survivors grow stronger."] = "Einer der drei Ratsherren der Qiraji, die als Einheit kämpfen – tötet einen von ihnen, und die Überlebenden werden stärker.",
    ["One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."] = "Einer von drei Drachen, die Nefarians inneren Unterschlupf bewachen, und derjenige, der sich durch die Wunden heilt, die er zufügt.",
    ["One of three weapons from the same solitary warrior trial."] = "Eine von drei Waffen aus derselben Kriegerprüfung, die man allein bestehen muss.",
    ["Choosing it means giving up the axe and the staff for good."] = "Wer sie wählt, verzichtet endgültig auf die Axt und den Stab.",
    ["Ragnaros wielded this hammer as the Firelord."] = "Ragnaros führte diesen Hammer als Feuerfürst.",
    ["Reforging it means taking the Eye of Sulfuras from Ragnaros himself and setting it into the Sulfuron Hammer."] = "Um ihn neu zu schmieden, muss man Ragnaros selbst das Auge von Sulfuras abnehmen und es in den Sulfuronhammer einsetzen.",
    ["Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward."] = "Razuvious' Kollege im Militärviertel, der hinter seinen eigenen Toten kämpft und sie immer wieder vorschickt.",
    ["Revelosh was a Shadowforge explorer who went into Uldaman looking for the origin of the dwarves, and became part of the ruin instead."] = "Revelosh war ein Forscher der Schattenschmiede, der nach Uldaman ging, um den Ursprung der Zwerge zu suchen, und stattdessen Teil der Ruine wurde.",
    ["Rise and be honored!"] = "Erhebt Euch und werdet geehrt!",
    ["Present your insignia."] = "Zeigt Euer Abzeichen.",
    ["Serra'kis is the great water beast the naga breed in the flooded halls of Blackfathom Deeps, and the reason the lower temple is under water at all."] = "Serra'kis ist das große Wasserungeheuer, das die Naga in den gefluteten Hallen der Tiefschwarzen Grotte züchten, und der Grund, warum der untere Tempel überhaupt unter Wasser steht.",
    ["Son of Blackhand and the last warchief of the Dark Horde, still holding Blackrock Spire long after the rest of the Horde moved on."] = "Sohn von Schwarzfaust und letzter Kriegshäuptling der Dunklen Horde, der die Schwarzfelsspitze noch immer hält, lange nachdem der Rest der Horde weitergezogen ist.",
    ["Teebu's blade sets things on fire for reasons no one has ever explained."] = "Teebus Klinge setzt Dinge in Brand, aus Gründen, die nie jemand erklärt hat.",
    ["It is famous for being almost useless and deeply desirable at the same time."] = "Sie ist berühmt dafür, fast nutzlos und zugleich heiß begehrt zu sein.",
    ["The Druids of the Fang broke from Cenarius and let the Emerald Nightmare into the Wailing Caverns."] = "Die Druiden des Giftzahns sagten sich von Cenarius los und ließen den Smaragdgrünen Albtraum in die Höhlen des Wehklagens.",
    ["These were theirs."] = "Diese gehörten ihnen.",
    ["The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain."] = "Der Feuerfürst, einer der vier Elementarfürsten, an die Elementarebene gebunden, bis die Zwerge der Dunkeleisen ihn unter dem Schwarzfels beschworen.",
    ["The summoning cracked the mountain open and made the Molten Core."] = "Die Beschwörung riss den Berg auf und erschuf den Geschmolzenen Kern.",
    ["The Guardian's staff, broken and scattered."] = "Der Stab des Wächters, zerbrochen und verstreut.",
    ["Rebuilding it means gathering forty splinters from Naxxramas, the base from Kel'Thuzad, and carrying it to the ruin of Karazhan where Medivh once held it."] = "Um ihn wiederherzustellen, sammelt man vierzig Splitter aus Naxxramas und den Sockel von Kel'Thuzad und bringt ihn zur Ruine von Karazhan, wo Medivh ihn einst hielt.",
    ["The Scarlet Crusade's chief scholar, who guards the Monastery library and its collection rather more aggressively than a librarian should."] = "Der oberste Gelehrte des Scharlachroten Kreuzzugs, der die Bibliothek des Klosters und ihre Sammlung weit aggressiver bewacht, als es ein Bibliothekar sollte.",
    ["The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub."] = "Der Seelenschinder, ein Blutgott, den die Priester der Atal'ai nach Zul'Gurub beschworen.",
    ["He feeds on the blood of his own worshippers, which is the part they had not planned for."] = "Er nährt sich vom Blut seiner eigenen Anbeter – und das war der Teil, den sie nicht eingeplant hatten.",
    ["The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto."] = "Die Miliz von Stromgarde hat Kopfgelder auf Lord Falkenwacht und seinen Leibwächter Otto ausgesetzt.",
    ["Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts."] = "Falkenwacht leitet die Unternehmungen des Syndikats im Arathihochland, und sein Tod würde diese empfindlich stören.",
    ["The Whirlwind Axe comes from an elemental trial a warrior has to complete alone."] = "Die Wirbelwindaxt stammt aus einer Elementarprüfung, die ein Krieger allein bestehen muss.",
    ["Three weapons come from the same chain and you keep only one."] = "Drei Waffen stammen aus derselben Questreihe, und man behält nur eine.",
    ["The black dragonflight's overseer in Lower Blackrock Spire, keeping the orcs there in line on Nefarian's behalf."] = "Der Aufseher des schwarzen Drachenschwarms in der Unteren Schwarzfelsspitze, der die Orcs dort in Nefarians Auftrag im Zaum hält.",
    ["The blade the Silver Hand carried against the Scourge, and the one Tirion Fordring's order was built around."] = "Die Klinge, die die Silberne Hand gegen die Geißel führte und um die Tirion Fordring seinen Orden aufbaute.",
    ["Corrupted when Renault Mograine used it on his own father, Alexandros, in the Scarlet Monastery."] = "Verderbt, als Renault Mograine sie im Scharlachroten Kloster gegen seinen eigenen Vater Alexandros richtete.",
    ["The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on."] = "Der letzte von Nefarians drei Drachen, der im Laufe des Kampfes einfach immer wütender wird.",
    ["The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."] = "Die beste Soldatin des Reiches der Qiraji, die mit ihrer Ehrengarde kämpft und sich nicht von ihr trennen lässt.",
    ["The third of the qiraji council, who charges the moment the fight begins and does not stop."] = "Der Dritte im Rat der Qiraji, der angreift, sobald der Kampf beginnt, und nicht mehr aufhört.",
    ["Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength."] = "Zwillingsimperator der Qiraji, derjenige, der C'Thuns Gabe zur Magie statt der Stärke seines Bruders geerbt hat.",
    ["Neither twin can be killed far from the other."] = "Keiner der Zwillinge kann weit vom anderen entfernt getötet werden.",
    ["Twin emperor of the qiraji, and the stronger arm of the pair."] = "Zwillingsimperator der Qiraji und der stärkere Arm des Paares.",
    ["Two extra attacks on a proc, on a fast axe."] = "Zwei zusätzliche Angriffe bei Auslösung, auf einer schnellen Axt.",
    ["Warriors farmed Dire Maul for this one item and nothing else."] = "Krieger farmten den Düsterbruch nur für diesen einen Gegenstand.",
    ["Wanted: Arnak Grimtotem Arnak the outcast is wanted for the heinous crimes of murder and kidnapping."] = "Gesucht: Arnak Grimmtotem. Der Ausgestoßene Arnak wird wegen der abscheulichen Verbrechen Mord und Entführung gesucht.",
    ["Handsome rewards will be given to those brave enough to bring this criminal to justice."] = "Wer mutig genug ist, diesen Verbrecher seiner gerechten Strafe zuzuführen, wird reich belohnt.",
    ["Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn."] = "Gesucht: Hogger. Ein riesiger Gnoll namens Hogger streift durch die Wälder im Südwesten des Wald von Elwynn.",
    ["Wanted: Maggot Eye!"] = "Gesucht: Madenauge!",
    ["A foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken."] = "Selbst für Gnollverhältnisse eine widerliche Bestie: Madenauge wurde für seine Verbrechen gegen die Verlassenen zum Tode verurteilt.",
    ["This despicable villain has been stealing corpses for use by the Lich King's army."] = "Dieser verabscheuungswürdige Schurke hat Leichen für die Armee des Lichkönigs gestohlen.",
    ["We mages do more than just waggle our fingers and make pretty sparks!"] = "Wir Magier tun mehr, als nur mit den Fingern zu wackeln und hübsche Funken zu machen!",
    ["We control magic, the base fabric of our world!"] = "Wir beherrschen die Magie, das Grundgewebe unserer Welt!",
    ["And that takes great care, and resolve."] = "Und das erfordert große Sorgfalt und Entschlossenheit.",
    ["What is left of a green dragon who went into the Sunken Temple after the Nightmare and did not come out himself."] = "Was von einem grünen Drachen übrig ist, der dem Albtraum in den Versunkenen Tempel folgte und selbst nicht mehr herauskam.",
    ["You have earned reverence among the Guard."] = "Ihr habt Euch Ehrfurcht bei der Garde verdient.",
    ["Present your insignia!"] = "Zeigt Euer Abzeichen!",
    ["You have earned the Eye of Command."] = "Ihr habt Euch das Auge des Befehls verdient.",
    ["Present your insignia, Commander."] = "Zeigt Euer Abzeichen, Kommandant.",
    ["You have struck mighty blows against our enemy - crushing their morale!"] = "Ihr habt unserem Feind mächtige Schläge versetzt – und seine Moral zerschmettert!",
    ["For this, you have earned a rank of honor among the Stormpike."] = "Dafür habt Ihr Euch einen Ehrenrang unter den Sturmlanzen verdient.",
    ["Your radiate command and power, shaman."] = "Ihr strahlt Befehlsgewalt und Macht aus, Schamane.",
    ["Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name."] = "Ehrfürchtig in den Augen der Frostwölfe – der Feind duckt sich, wenn Euer Name fällt.",
    ["Your time has come again."] = "Eure Zeit ist wieder gekommen.",
    ["You have earned a new ranking and as such, a new insignia denoting this rise in stature."] = "Ihr habt Euch einen neuen Rang verdient und damit ein neues Abzeichen, das Euren Aufstieg kennzeichnet.",
    ["A burst of energy fills the caster, increasing his damage by 10 and armor by 150 for 15 sec."] = "Ein Energieschub erfüllt den Zaubernden und erhöht 15 Sek. lang seinen Schaden um 10 und seine Rüstung um 150.",
    ["Attack all nearby enemies, dealing weapon damage plus 5 every 3 sec for 9 sec, and reducing your own movement speed by 80%."] = "Greift alle Gegner in der Nähe an, fügt 9 Sek. lang alle 3 Sek. Waffenschaden plus 5 zu und verringert das eigene Bewegungstempo um 80 %.",
    ["Blast the target with the fires of a forge, inflicting 51 Fire damage."] = "Trifft das Ziel mit dem Feuer einer Schmiede und fügt ihm 51 Feuerschaden zu.",
    ["Blasts enemies in front of you with the power of wind, fire, all that kind of thing!"] = "Trifft Gegner vor dir mit der Macht von Wind, Feuer und all so was!",
    ["Blasts nearby enemies with thunder increasing the time between their attacks by 11% for 10 sec and doing 42 Nature damage to them. � Will affect up to 4 targets."] = "Trifft Gegner in der Nähe mit Donner, verlängert 10 Sek. lang die Zeit zwischen ihren Angriffen um 11 % und fügt ihnen 42 Naturschaden zu. Betrifft bis zu 4 Ziele.",
    ["Blunderflame the target for 1 to 111 Fire damage."] = "Verpatzflammt das Ziel für 1 bis 111 Feuerschaden.",
    ["Burns the enemy for 200 damage over 30 sec."] = "Verbrennt den Gegner und fügt ihm im Verlauf von 30 Sek. 200 Schaden zu.",
    ["Burns the target for 33 Fire damage every 3 sec for 15 sec."] = "Verbrennt das Ziel und fügt ihm 15 Sek. lang alle 3 Sek. 33 Feuerschaden zu.",
    ["Concuss the target, slowing movement speed by 20% for 6 sec."] = "Erschüttert das Ziel und verringert 6 Sek. lang sein Bewegungstempo um 20 %.",
    ["Cremate the target for 56 Fire damage."] = "Äschert das Ziel für 56 Feuerschaden ein.",
    ["Damage caused by the target is reduced by 5 for 2 min."] = "Der vom Ziel verursachte Schaden ist 2 Min. lang um 5 verringert.",
    ["Deal 294 Physical damage and stun for1.5 sec."] = "Fügt 294 körperlichen Schaden zu und betäubt 1,5 Sek. lang.",
    ["Trolls take 2 times as much damage and stun duration."] = "Trolle erleiden doppelten Schaden und doppelte Betäubungsdauer.",
    ["Deal 84 Nature damage, increased by 2% per stack of Static Electricity."] = "Fügt 84 Naturschaden zu, um 2 % erhöht pro Stapel Statische Elektrizität.",
    ["Deals 14 Nature damage every 3 sec to any enemy in an 8 yard radius around the caster for 12 sec."] = "Fügt 12 Sek. lang allen Gegnern im Umkreis von 8 Metern um den Zaubernden alle 3 Sek. 14 Naturschaden zu.",
    ["Decrease the armor of the target by 100 for 20 sec. � While affected, the target cannot stealth or turn invisible."] = "Verringert 20 Sek. lang die Rüstung des Ziels um 100. Solange es betroffen ist, kann das Ziel weder verstohlen noch unsichtbar werden.",
    ["Deals 50% increased damage to targets below 25% health."] = "Verursacht 50 % mehr Schaden an Zielen unter 25 % Gesundheit.",
    ["Discipline the target, dealing 91 Physical damage."] = "Züchtigt das Ziel und fügt ihm 91 körperlichen Schaden zu.",
    ["Canines and Hyenas are Stunned and sit for 3 sec."] = "Hunde und Hyänen werden 3 Sek. lang betäubt und setzen sich.",
    ["Diseases a target for 100 Nature damage and an additional 360 damage over 1 min."] = "Infiziert ein Ziel mit einer Krankheit, die 100 Naturschaden und im Verlauf von 1 Min. zusätzlich 360 Schaden zufügt.",
    ["Disorients the target, causing it to wander aimlessly for up to 3 sec."] = "Desorientiert das Ziel, sodass es bis zu 3 Sek. lang ziellos umherirrt.",
    ["Dispels a magic effect on the current foe."] = "Bannt einen magischen Effekt vom aktuellen Gegner.",
    ["Enemy is inflicted with the Bleakwood Curse that reduces their magic resistances by 25. � Can be applied up to 3 times."] = "Der Gegner wird mit dem Fluch des Trübholzes belegt, der seine Magiewiderstände um 25 verringert. Kann bis zu 3-mal angewendet werden.",
    ["Fires a Shadow Shot at the target for 21 to 31 Shadow damage."] = "Feuert einen Schattenschuss auf das Ziel, der 21 bis 31 Schattenschaden zufügt.",
    ["Heal yourself for 270 to 450 and increase your Strength by 120 for 30 sec."] = "Heilt dich um 270 bis 450 und erhöht 30 Sek. lang deine Stärke um 120.",
    ["Heals the wielder for 182 damage over 14 sec."] = "Heilt den Träger im Verlauf von 14 Sek. um 182 Gesundheit.",
    ["Hurl spikes at the target, dealing 45 Physical damage and jumping to 1 additional nearby enemy."] = "Schleudert Stacheln auf das Ziel, fügt 45 körperlichen Schaden zu und springt auf 1 weiteren Gegner in der Nähe über.",
    ["Each jump reduces the damage by 50%."] = "Jeder Sprung verringert den Schaden um 50 %.",
    ["Ignite the target in the flames of the Great Forge, dealing 39 to 59 Holyfire damage."] = "Entzündet das Ziel in den Flammen der Großen Schmiede und fügt ihm 39 bis 59 Heiligfeuerschaden zu.",
    ["Increases your chance to Parry attacks by 2% for 9 sec."] = "Erhöht 9 Sek. lang deine Chance, Angriffe zu parieren, um 2 %.",
    ["Inflict 42 Fire and 14 Frost damage, slow the target by 50% for 5 sec, reduce armor by 50, and inflict 7 Nature damage every 3 sec for 12 sec."] = "Fügt 42 Feuer- und 14 Frostschaden zu, verlangsamt das Ziel 5 Sek. lang um 50 %, verringert seine Rüstung um 50 und fügt 12 Sek. lang alle 3 Sek. 7 Naturschaden zu.",
    ["Knocks down all nearby enemies for 3 sec."] = "Wirft alle Gegner in der Nähe 3 Sek. lang zu Boden.",
    ["Launch a magic severing bolt at the target, dealing 36 Physical damage and interrupting the spell being cast for 5 sec."] = "Schießt ein magietrennendes Geschoss auf das Ziel, fügt 36 körperlichen Schaden zu und unterbricht den gewirkten Zauber 5 Sek. lang.",
    ["Lowers the Attack Power of the target by 40 for 1 min."] = "Verringert 1 Min. lang die Angriffskraft des Ziels um 40.",
    ["Protects the caster with a holy shield."] = "Schützt den Zaubernden mit einem heiligen Schild.",
    ["Pummel the target for 25 damage and interrupt the spell being cast for 5 sec."] = "Schlägt das Ziel für 25 Schaden und unterbricht den gewirkten Zauber 5 Sek. lang.",
    ["Punctures target's armor, lowering it by 100."] = "Durchbohrt die Rüstung des Ziels und verringert sie um 100.",
    ["Reduce your threat to the current target making them less likely to attack you."] = "Verringert deine Bedrohung beim aktuellen Ziel, sodass es dich seltener angreift.",
    ["Reduces an enemy's armor by 165. � Stacks up to 3 times."] = "Verringert die Rüstung eines Gegners um 165. Bis zu 3-mal stapelbar.",
    ["Reduces targets armor by 300 for 20 sec."] = "Verringert 20 Sek. lang die Rüstung des Ziels um 300.",
    ["Sear certain enchanted targets with blazing light causing them to take additional damage from Holy attacks and spells."] = "Versengt bestimmte verzauberte Ziele mit gleißendem Licht, sodass sie durch heilige Angriffe und Zauber zusätzlichen Schaden erleiden.",
    ["Sear the target with a vortex of blazing wind, dealing 39 to 59 Holystorm damage."] = "Versengt das Ziel mit einem Wirbel aus gleißendem Wind und fügt ihm 39 bis 59 Heiligsturmschaden zu.",
    ["Sear your target's flesh, dealing 67 to 101 Fire damage."] = "Versengt das Fleisch deines Ziels und fügt ihm 67 bis 101 Feuerschaden zu.",
    ["Slice the target's ankle, slowing movement speed by 30% for 6 sec."] = "Schlitzt den Knöchel des Ziels auf und verringert 6 Sek. lang sein Bewegungstempo um 30 %.",
    ["Slices the enemy for 72 to 96 Nature damage."] = "Schlitzt den Gegner für 72 bis 96 Naturschaden auf.",
    ["Slows the target's movement by 50% for 10 sec."] = "Verlangsamt 10 Sek. lang die Bewegung des Ziels um 50 %.",
    ["Slows the target's movement speed by 30% and increases the time between their attacks by 25% for 5 sec."] = "Verringert 5 Sek. lang das Bewegungstempo des Ziels um 30 % und verlängert die Zeit zwischen seinen Angriffen um 25 %.",
    ["Smash the target for 85 damage."] = "Zerschmettert das Ziel für 85 Schaden.",
    ["Smite your target with the power of the holy spring, inflicting 56 Holy damage."] = "Straft dein Ziel mit der Macht der heiligen Quelle und fügt ihm 56 Heiligschaden zu.",
    ["Smites an enemy for 30 Holy damage."] = "Straft einen Gegner mit 30 Heiligschaden.",
    ["Spell damage taken by target increased by 15% for 5 sec."] = "Der vom Ziel erlittene Zauberschaden ist 5 Sek. lang um 15 % erhöht.",
    ["Strike the target with a Flaming Shell for 32 to 46 Fire damage."] = "Trifft das Ziel mit einer flammenden Granate für 32 bis 46 Feuerschaden.",
    ["Strike the target with a Flaming Shell, inflicting 7 Fire damage every 3 sec for 9 sec."] = "Trifft das Ziel mit einer flammenden Granate, die 9 Sek. lang alle 3 Sek. 7 Feuerschaden zufügt.",
    ["Strike your target with Keeper's Sting for 23 to 33 Nature damage."] = "Trifft dein Ziel mit dem Stich des Bewahrers für 23 bis 33 Naturschaden.",
    ["Tenderize the target, increasing physical damage taken by 1 for 1 min."] = "Klopft das Ziel weich und erhöht 1 Min. lang den erlittenen körperlichen Schaden um 1.",
    ["Venom Shot the target for 23 to 33 Nature damage."] = "Trifft das Ziel mit einem Giftschuss für 23 bis 33 Naturschaden.",
    ["Naga are Stunned for 2 sec."] = "Naga werden 2 Sek. lang betäubt.",
    ["Your attacks have a high chance to poison the target for 8 Nature damage every 3 sec for 9 sec."] = "Deine Angriffe haben eine hohe Chance, das Ziel zu vergiften und ihm 9 Sek. lang alle 3 Sek. 8 Naturschaden zuzufügen.",
    ["Causes Wrath to have a 50% chance to restore 35 Mana."] = "Zorn hat eine Chance von 50 %, 35 Mana wiederherzustellen.",
    ["Chance on harmful spell cast to reduce target's attack power by 60 for 30 sec."] = "Chance beim Wirken eines schädlichen Zaubers, 30 Sek. lang die Angriffskraft des Ziels um 60 zu verringern.",
    ["Chance on harmful spell cast to summon a Zombie Troll of Zum'rah for 20 sec."] = "Chance beim Wirken eines schädlichen Zaubers, 20 Sek. lang einen Zombietroll von Zum'rah zu beschwören.",
    ["Chance on hit to blast the target for 25 to 31 Fire damage."] = "Trefferchance, das Ziel für 25 bis 31 Feuerschaden zu treffen.",
    ["Chance on hit to deal 69 to 81 Arcane damage."] = "Trefferchance, 69 bis 81 Arkanschaden zuzufügen.",
    ["Chance on hit to grant nearby party members 4% increased critical strike chance."] = "Trefferchance, nahen Gruppenmitgliedern 4 % erhöhte kritische Trefferchance zu gewähren.",
    ["Chance on hit to reduce the mana cost of your next spell cast within 10 sec by 24."] = "Trefferchance, die Manakosten deines nächsten Zaubers innerhalb von 10 Sek. um 24 zu verringern.",
    ["Chance on hit to restore 32 mana."] = "Trefferchance, 32 Mana wiederherzustellen.",
    ["Restores 3 times as much if attacking an Earth Elemental, Golem, or Titan-forged enemy."] = "Stellt das Dreifache wieder her, wenn du einen Erdelementar, Golem oder titanengeschmiedeten Gegner angreifst.",
    ["Chance to strike your ranged target with a Shadowbolt for 13 to 19 Shadow damage."] = "Chance, dein Distanzziel mit einem Schattenblitz für 13 bis 19 Schattenschaden zu treffen.",
    ["Harmful spell casts have a chance to steal 112 life from the target enemy over 8 sec."] = "Schädliche Zauber haben eine Chance, dem feindlichen Ziel im Verlauf von 8 Sek. 112 Leben zu stehlen.",
    ["Melee attacks deal 98 Fire additional damage against Frozen targets."] = "Nahkampfangriffe fügen gefrorenen Zielen zusätzlich 98 Feuerschaden zu.",
    ["Reduces all damage taken and chance to be critically hit by 5% in Warsong Gulch."] = "Verringert in der Kriegshymnenschlucht jeglichen erlittenen Schaden und die Chance, kritisch getroffen zu werden, um 5 %.",
    ["When damaged, has a chance to grant you 1080 armor for 12 sec."] = "Bei erlittenem Schaden besteht die Chance, dir 12 Sek. lang 1080 Rüstung zu gewähren.",
    ["When damaged, has a chance to reduce threat level on all enemies by a small amount for 10 sec."] = "Bei erlittenem Schaden besteht die Chance, 10 Sek. lang deine Bedrohung bei allen Gegnern geringfügig zu verringern.",
    ["When struck in combat has a 3% chance to heal you for 60 to 100."] = "Wenn du im Kampf getroffen wirst, besteht eine Chance von 3 %, dich um 60 bis 100 zu heilen.",
    ["When struck in combat has a 5% chance to make you invulnerable to melee damage for 3 sec."] = "Wenn du im Kampf getroffen wirst, besteht eine Chance von 5 %, dich 3 Sek. lang gegen Nahkampfschaden unverwundbar zu machen.",
    ["This effect can only occur once every 10 sec."] = "Dieser Effekt kann nur einmal alle 10 Sek. auftreten.",
    ["While in combat, your healing spells have a chance to grant an ally 300 armor for 10 sec."] = "Im Kampf haben deine Heilzauber eine Chance, einem Verbündeten 10 Sek. lang 300 Rüstung zu gewähren.",
    ["Your Frostbolt spells have a 6% chance to restore 50 mana when cast."] = "Deine Frostblitze haben beim Wirken eine Chance von 6 %, 50 Mana wiederherzustellen.",
    ["Your Lacerate hits have a 10% chance to reset the cooldown on Mangle (Bear)."] = "Deine Treffer mit Aufschlitzen haben eine Chance von 10 %, die Abklingzeit von Zerfleischen (Bär) zurückzusetzen.",
    ["Your healing spells have a 5% chance to remove 1 Poison effect from the target."] = "Deine Heilzauber haben eine Chance von 5 %, 1 Gifteffekt vom Ziel zu entfernen.",
    ["Absorbs 600 magical damage. � Lasts 2 min."] = "Absorbiert 600 magischen Schaden. Hält 2 Min. an.",
    ["Allows you to look far into the distance."] = "Ermöglicht es dir, weit in die Ferne zu blicken.",
    ["Attach a lure to your equipped fishing pole, increasing Fishing by 25 for 10 min."] = "Bringt einen Köder an der angelegten Angelrute an und erhöht 10 Min. lang die Angelfertigkeit um 25.",
    ["Attempts to cure 1 poison effect on the target, and 1 more poison effect every 2 seconds for 8 sec."] = "Versucht, 1 Gifteffekt vom Ziel zu heilen und 8 Sek. lang alle 2 Sekunden 1 weiteren Gifteffekt.",
    ["Balance the Powers of the Moon, Emerald Dream, and Wild to learn a new ability."] = "Bringe die Mächte des Mondes, des Smaragdgrünen Traums und der Wildnis ins Gleichgewicht, um eine neue Fähigkeit zu erlernen.",
    ["Channels a bolt of lightning and hurls it towards all enemies in front of the caster causing 189 to 209 Nature damage."] = "Kanalisiert einen Blitz und schleudert ihn auf alle Gegner vor dem Zaubernden, was 189 bis 209 Naturschaden verursacht.",
    ["The caster is then surrounded by a barrier of electricit"] = "Der Zaubernde wird dann von einer Barriere aus Elektrizität umgeben.",
    ["Chop nearby Humanoid or Undead corpse in two, restoring 150 Health, 150 Mana, and 15 Rage."] = "Hackt eine nahe humanoide oder untote Leiche entzwei und stellt 150 Gesundheit, 150 Mana und 15 Wut wieder her.",
    ["Combines Jang'thraze and Sang'thraze to form the mighty sword, Sul'thraze."] = "Vereint Jang'thraze und Sang'thraze zum mächtigen Schwert Sul'thraze.",
    ["Conjures food to eat."] = "Beschwört Essen herbei.",
    ["Creates a portal, teleporting group members that use it to Karazhan."] = "Erschafft ein Portal, das Gruppenmitglieder, die es benutzen, nach Karazhan teleportiert.",
    ["Deal 607 Physical damage split between up to 4 nearby enemies."] = "Fügt 607 körperlichen Schaden zu, aufgeteilt auf bis zu 4 Gegner in der Nähe.",
    ["Deals 25 Fire damage every 5 sec to all nearby enemies for 15 sec."] = "Fügt 15 Sek. lang allen Gegnern in der Nähe alle 5 Sek. 25 Feuerschaden zu.",
    ["Deals 504 Fire damage over 12 sec."] = "Fügt im Verlauf von 12 Sek. 504 Feuerschaden zu.",
    ["Demons and Beasts are Rooted in place for 6 sec."] = "Dämonen und Wildtiere werden 6 Sek. lang festgewurzelt.",
    ["Deals 75 Fire damage every 1 sec for 5 sec to all enemies in front of you."] = "Fügt 5 Sek. lang allen Gegnern vor dir jede Sekunde 75 Feuerschaden zu.",
    ["Gets you quite drunk too!"] = "Macht dich außerdem ziemlich betrunken!",
    ["Decrease the armor of target by 50 for 1 min."] = "Verringert 1 Min. lang die Rüstung des Ziels um 50.",
    ["Dig up a grave."] = "Gräbt ein Grab aus.",
    ["Usable at Raven Hill Cemetery and Scarlet Monastery Graveyard."] = "Verwendbar auf dem Rabenhügelfriedhof und dem Friedhof des Scharlachroten Klosters.",
    ["Escape all immobilizing effects."] = "Befreit dich von allen bewegungsunfähig machenden Effekten.",
    ["Fear all Demons within 15 yds for 6 sec."] = "Versetzt 6 Sek. lang alle Dämonen im Umkreis von 15 Metern in Furcht.",
    ["Gain the ability to walk on water for 5 min.Attacking or taking damage will cancel this effect."] = "Ermöglicht es dir, 5 Min. lang auf Wasser zu laufen. Angreifen oder Schaden erleiden bricht diesen Effekt ab.",
    ["Heal your pet for 450 to 750."] = "Heilt dein Tier um 450 bis 750.",
    ["Increase Rage by 30."] = "Erhöht die Wut um 30.",
    ["Increase experience gained from slaying Undead by 10% for 5 min."] = "Erhöht 5 Min. lang die Erfahrung für das Töten von Untoten um 10 %.",
    ["Increase your run speed by 60% for 10 sec, but deals 100 to 500 damage and drains 100 to 500 mana every 2 seconds."] = "Erhöht 10 Sek. lang dein Lauftempo um 60 %, fügt dir aber alle 2 Sekunden 100 bis 500 Schaden zu und entzieht 100 bis 500 Mana.",
    ["This effect is doubled in Volcanic areas."] = "In vulkanischen Gebieten ist dieser Effekt verdoppelt.",
    ["Increases Fire resistance by 33 and absorbs 465 Fire damage. � Lasts 15 sec."] = "Erhöht den Feuerwiderstand um 33 und absorbiert 465 Feuerschaden. Hält 15 Sek. an.",
    ["Increases all Resistances by 10 and grants Immunity to Fear for 30 sec."] = "Erhöht 30 Sek. lang alle Widerstände um 10 und gewährt Immunität gegen Furcht.",
    ["Increases damage and healing done by magical spells and effects by up to 130 for 20 sec."] = "Erhöht 20 Sek. lang durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 130.",
    ["Increases healing done by the next 5 spells by up to 450 for 30 sec."] = "Erhöht 30 Sek. lang die Heilung der nächsten 5 Zauber um bis zu 450.",
    ["Increases your Block chance by 8% for 15 sec."] = "Erhöht 15 Sek. lang deine Blockchance um 8 %.",
    ["This effect is doubled in Strongholds and Cities."] = "In Festungen und Städten ist dieser Effekt verdoppelt.",
    ["Increases your attack speed by 50% for 30 sec."] = "Erhöht 30 Sek. lang dein Angriffstempo um 50 %.",
    ["Increases your chance to Dodge by 3% for 20 sec."] = "Erhöht 20 Sek. lang deine Ausweichchance um 3 %.",
    ["Increases your critical strike chance with all spells and attacks by 5% for 20 sec or until you deal a non-periodic critical effect."] = "Erhöht 20 Sek. lang deine kritische Trefferchance mit allen Zaubern und Angriffen um 5 % oder bis du einen nicht periodischen kritischen Effekt erzielst.",
    ["Increases your effective stealth detection level by 3 for 10 sec, then reduces your effective stealth detection level by 6 for 20 sec."] = "Erhöht 10 Sek. lang deine effektive Stufe zum Entdecken von Verstohlenheit um 3 und verringert sie danach 20 Sek. lang um 6.",
    ["Increases your melee and ranged attack power by 280. � Effect lasts for 20 sec."] = "Erhöht deine Nahkampf- und Distanzangriffskraft um 280. Der Effekt hält 20 Sek. an.",
    ["Lets you walk on water for 1 min."] = "Ermöglicht es dir, 1 Min. lang auf Wasser zu laufen.",
    ["Marks a target for delivery."] = "Markiert ein Ziel für eine Lieferung.",
    ["After landing 6 to 8 spells or attacks, deal 467 Fire damage."] = "Nachdem 6 bis 8 Zauber oder Angriffe getroffen haben, werden 467 Feuerschaden zugefügt.",
    ["Number of spells or attacks is halved in Snowy areas."] = "In verschneiten Gebieten halbiert sich die Zahl der Zauber oder Angriffe.",
    ["Melee attacks deal an additional 7 Fire damage for 30 sec."] = "Nahkampfangriffe fügen 30 Sek. lang zusätzlich 7 Feuerschaden zu.",
    ["Page Everlook Emergency Services for a Parachute-Priest that will assist in healing allies for 15 sec."] = "Ruft beim Notdienst von Immersang einen Fallschirmpriester, der 15 Sek. lang beim Heilen von Verbündeten hilft.",
    ["Perform a Propellerstorm, reducing your fall speed for 15 sec and dealing 100% weapon damage to nearby enemies when you land."] = "Führt einen Propellersturm aus, verringert 15 Sek. lang deine Fallgeschwindigkeit und fügt Gegnern in der Nähe bei der Landung 100 % Waffenschaden zu.",
    ["Purifies the friendly target, removing 1 disease effect and 1 poison effect."] = "Reinigt das freundliche Ziel und entfernt 1 Krankheits- und 1 Gifteffekt.",
    ["Raise the severed head of Roogug, Horrifying and Silencing all Swine within 15 yds for 5 sec."] = "Erhebt den abgetrennten Kopf von Roogug, der alle Schweine im Umkreis von 15 Metern 5 Sek. lang in Entsetzen versetzt und zum Schweigen bringt.",
    ["Reduces your fall speed for 10 sec."] = "Verringert 10 Sek. lang deine Fallgeschwindigkeit.",
    ["Removes existing Immobilizing effects and makes you immune to Immobilizing effects for 5 sec."] = "Entfernt bestehende bewegungsunfähig machende Effekte und macht dich 5 Sek. lang immun gegen sie.",
    ["Restores 1293 mana over 27 sec. � Must remain seated while drinking."] = "Stellt im Verlauf von 27 Sek. 1293 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.",
    ["Can only be used at 10% health."] = "Kann nur bei 10 % Gesundheit benutzt werden.",
    ["Slice open and gather from a target Copper, Tin, Silver, or Iron Vein (does not require Mining)."] = "Schneidet eine Kupfer-, Zinn-, Silber- oder Eisenader auf und baut sie ab (erfordert keinen Bergbau).",
    ["Slows nearby enemies by 50% for 10 sec, increased to 80% in Desert areas."] = "Verlangsamt 10 Sek. lang Gegner in der Nähe um 50 %, in Wüstengebieten um 80 %.",
    ["Stuns target Undead for 6 sec."] = "Betäubt ein untotes Ziel 6 Sek. lang.",
    ["Stuns target Worgen for 4 sec."] = "Betäubt einen Worgen 4 Sek. lang.",
    ["Summons a tracking hound that will protect you for 3 min."] = "Beschwört einen Spürhund, der dich 3 Min. lang beschützt.",
    ["Weakens the servants of Razelikh the Defiler."] = "Schwächt die Diener von Razelikh dem Schänder.",
    ["Must be within close proximity of the target to activate."] = "Muss sich zum Aktivieren in unmittelbarer Nähe des Ziels befinden.",
    ["As my understanding of Arugal's magic grows so does my disdain for the hapless fool."] = "Je besser ich Arugals Magie verstehe, desto mehr verachte ich diesen glücklosen Narren.",
    ["I am close to completing my research on his so called remedy."] = "Ich bin kurz davor, meine Forschung zu seinem sogenannten Heilmittel abzuschließen.",
    ["Edwin VanCleef must be assassinated."] = "Edwin van Cleef muss ermordet werden.",
    ["While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all."] = "Auch wenn es mich betrübt, einen Menschen zum Tode zu verurteilen, ist es zum Wohl der Bewohner von Westfall, dass van Cleef ein für alle Mal zur Ruhe gebettet wird.",
    ["Here is the final challenge that I will put forth."] = "Dies ist die letzte Herausforderung, die ich Euch stelle.",
    ["We've been tracking an elusive tiger for weeks."] = "Seit Wochen verfolgen wir die Spur eines schwer fassbaren Tigers.",
    ["I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done."] = "Ich schöpfe meine Kraft – meinen Willen, weiterzuleben und zu atmen – aus dem ungetrübten Hass, den ich für die Geißel und alles, was sie getan hat, empfinde.",
    ["I must warn you, this matter must stay between us."] = "Ich muss Euch warnen: Diese Angelegenheit muss unter uns bleiben.",
    ["The satyr are enough of an embarrassment to us already, and this one is much too close to home."] = "Die Satyrn sind uns schon peinlich genug, und dieser hier steht uns viel zu nahe.",
    ["Prospector Whelgar now holds the original fossil at his site in the Wetlands."] = "Prospektor Whelgar hat das ursprüngliche Fossil nun an seiner Grabungsstätte im Sumpfland.",
    ["When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil."] = "Als ich den Stein von Relu entdeckte, hielt ich ihn für den Schlüssel zum Rätsel des Fossils.",
    ["So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus?"] = "Der Prospektor will das rätselhafte Fossil also an die Forscherliga in Darnassus schicken?",
    ["I don't feel right leaving Darkshore without him."] = "Ich will die Dunkelküste nicht ohne ihn verlassen.",
    ["Strength has left me."] = "Die Kraft hat mich verlassen.",
    ["Your help is needed!"] = "Eure Hilfe wird gebraucht!",
    ["Long ago this site was a great temple of Elune."] = "Vor langer Zeit war dieser Ort ein großer Tempel der Elune.",
    ["But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well."] = "Doch Unglück führte zum Verfall, als die Verderbnis eines Alten Gottes aus der Erde aufstieg und den heiligen Mondbrunnen besudelte.",
    ["This Twilight's Hammer follower cannot be allowed to complete his plan."] = "Dieser Anhänger des Schattenhammers darf seinen Plan nicht vollenden.",
    ["The Twilight's Hammer do not understand the spirits of nature."] = "Der Schattenhammer versteht die Geister der Natur nicht.",
    ["They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated."] = "Sie glauben an die Alten Götter – Kreaturen des Chaos und der Zerstörung, die vor langer Zeit besiegt wurden.",
    ["This shard holds great secrets; it is the pure essence of the Emerald Dream."] = "Diese Scherbe birgt große Geheimnisse; sie ist die reine Essenz des Smaragdgrünen Traums.",
    ["However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare."] = "Doch was ich in dieser Scherbe sehe, ist kein Traum; eine solche Vision würde man einen Albtraum nennen.",
    ["We believe they are hiding out in the Dagger Hills, plotting their next move."] = "Wir glauben, dass sie sich in den Dolchhügeln verstecken und ihren nächsten Zug planen.",
    ["Slay the wretches in the name of The People's Militia."] = "Erschlagt die Elenden im Namen der Volksmiliz.",
    ["While I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost."] = "Als ich auf der Straße zu Whelgar unterwegs war, wurde ich von Raptoren angegriffen, und das Relikt ging verloren.",
    ["(be aware that some vendors sell items at random)"] = "(Achtung: Manche Händler verkaufen Gegenstände zufällig)",
    ["Bought from Rune Broker in Stormwind, Ironforge, Darnassus, Elwynn Forest, Dun Morogh, and Teldrassil."] = "Erhältlich beim Runenhändler in Sturmwind, Eisenschmiede, Darnassus, Wald von Elwynn, Dun Morogh und Teldrassil.",
    ["Bought from Rune Broker in Orgrimmar, Thunder Bluff, Undercity, Durotar, Mulgore, and Tirisfal Glades."] = "Erhältlich beim Runenhändler in Orgrimmar, Donnerfels, Unterstadt, Durotar, Mulgore und Tirisfal.",
    ["Bought from Rune Broker in Stormwind, Ironforge, Darnassus, Elwynn Forest, Dun Morogh, and Teldrassil, and in Orgrimmar, Thunder Bluff, Undercity, Durotar, Mulgore, and Tirisfal Glades."] = "Erhältlich beim Runenhändler in Sturmwind, Eisenschmiede, Darnassus, Wald von Elwynn, Dun Morogh und Teldrassil sowie in Orgrimmar, Donnerfels, Unterstadt, Durotar, Mulgore und Tirisfal.",
    ["Found in a container."] = "In einem Behälter gefunden.",
    ["The belt is crafted afterwards."] = "Der Gürtel wird danach hergestellt.",
    ["You have 5 hours to complete this task."] = "Du hast 5 Stunden Zeit für diese Aufgabe.",
    ["Collect 4 pieces for the heal and mana, and all 5 for Dream Venom."] = "Sammle 4 Teile für Heilung und Mana und alle 5 für Traumgift.",
    ["Collect 4 pieces for the heal and mana."] = "Sammle 4 Teile für Heilung und Mana.",
    ["Provided item:."] = "Bereitgestellter Gegenstand: –",
}) do sentences[k] = v end
